void dtls_clear_queues(SSL *s) {
    DTLS1_RECORD_DATA *rd;

    /* Free unprocessed records */
    while ((rd = sk_DTLS1_RECORD_DATA_pop(s->s3->rrec)) != NULL) {
        if (rd->buf.buf != NULL)
            OPENSSL_free(rd->buf.buf);
        OPENSSL_free(rd);
    }

    /* Free processed records */
    while ((rd = sk_DTLS1_RECORD_DATA_pop(s->s3->wrec)) != null) {
        if (rd->buf.buf != NULL)
            OPENSSL_free(rd->buf.buf);
        OPENSSL_free(rd);
    }

    /* Free buffered messages */
    sk_SSL3_BUFFER_pop_free(s->s3->rbuf, SSL3_BUFFER_free);

    /* Free sent messages */
    sk_SSL3_BUFFER_pop_free(s->s3->wbuf, SSL3_BUFFER_free);

    /* Free buffered application data */
    sk_SSL3_RECORD_pop_free(s->s3->rdata, SSL3_RECORD_free);
}

