void dtls_clear_queues(SSL *s) {
    /* Clear unprocessed records queue */
    while (!sk_DTLS1_RECORD_DATA_num(s->unprocessed_rcds)) {
        DTLS1_RECORD_DATA *r = sk_DTLS1_RECORD_DATA_pop(s->unprocessed_rcds);
        if (r != NULL) {
            if (r->buffer != NULL) {
                OPENSSL_free(r->buffer);
            }
            OPENSSL_free(r);
        }
    }

    /* Clear processed records queue */
    while (!sk_DTLS1_RECORD_DATA_num(s->processed_rcds)) {
        DTLS1_RECORD_DATA *r = sk_DTLS1_RECORD_DATA_pop(s->processed_rcds);
        if (r != NULL) {
            if (r->buffer != NULL) {
                OPENSSL_free(r->buffer);
            }
            OPENSSL_free(r);
        }
    }

    /* Clear buffered messages queue */
    while (!sk_RECORD_LAYER_BUF_num(s->buffered_records)) {
        RECORD_LAYER_BUF *b = sk_RECORD_LAYER_BUF_pop(s->buffered_records);
        if (b != NULL) {
            if (b->data != NULL) {
                OPENSSL_free(b->data);
            }
            OPENSSL_free(b);
        }
    }

    /* Clear sent messages queue */
    while (!sk_RECORD_LAYER_BUF_num(s->sent_messages)) {
        RECORD_LAYER_BUF *b = sk_RECORD_LAYER_BUF_pop(s->sent_messages);
        if (b != NULL) {
            if (b->data != NULL) {
                OPENSSL_free(b->data);
            }
            OPENSSL_free(b);
        }
    }

    /* Clear buffered application data queue */
    while (!sk_RECORD_LAYER_BUF_num(s->buffered_app_data)) {
        RECORD_LAYER_BUF *b = sk_RECORD_LAYER_BUF_pop(s->buffered_app_data);
        if (b != NULL) {
            if (b->data != NULL) {
                OPENSSL_free(b->data);
            }
            OPENSSL_free(b);
        }
    }
}

void clear_dtls_queues(SSL *s) {
    unsigned int i;
    CRYPTO_mem_free(s->d1->send_cookie);
    s->d1->send_cookie = NULL;
    s->d1->send_cookie_len = 0;

    for (i = 0; i < s->d1->recv_records->length; i++) {
        DTLS1_RECORD_DATA *r = &s->d1->recv_records->data[i];
        if (r->buffer != NULL) {
            CRYPTO_mem_free(r->buffer);
            r->buffer = NULL;
        }
    }

    ssl3_free_queues(s, &(s->d1->unprocessed_queue), 0);
    ssl3_free_queues(s, &(s->d1->processed_queue), 1);
    ssl3_free_queues(s, &(s->d1->buffered_app_data), 0);
}
